import math
from driver import measure_power, InstrumentError
from kx100 import KX100

def test():
    kx = KX100(seed=123, signal_hz=2.4e9, signal_dbm=-15.0)
    try:
        val = measure_power(kx, 2.4e9, 10)
        print("Success:", val)
    except InstrumentError as e:
        print("Error:", e)

if __name__ == "__main__":
    test()
